-- Aidan Hutchinson (NFL DET)
INSERT INTO players (league, first_name, last_name, slug, position, team_id)
SELECT 'NFL', 'Aidan', 'Hutchinson', 'aidan-hutchinson', 'DE', (SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'DET')
WHERE NOT EXISTS (SELECT 1 FROM players WHERE slug = 'aidan-hutchinson');
UPDATE players SET dob = COALESCE(dob, '2000-08-09'), height_in = COALESCE(height_in, 79), weight_lb = COALESCE(weight_lb, 268), headshot_path = COALESCE(headshot_path, '/players/aidan-hutchinson.png'), team_id = COALESCE((SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'DET'), team_id) WHERE slug = 'aidan-hutchinson' AND league = 'NFL';

-- Tear: aidan-hutchinson ACL 2026-11-15
INSERT INTO injuries (player_id, injury_type, injury_date, season, week, stadium_id, home_away, opponent_id, mechanism, body_side, phase, severity_notes, source)
SELECT p.id, 'ACL', '2026-11-15', COALESCE((SELECT CAST(s.v AS UNSIGNED) FROM settings s WHERE s.k = 'current_season'), 2026),
       10, (SELECT id FROM stadiums WHERE league = 'NFL' AND slug = 'allianz-arena'), 'home', (SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'NE'), 'non_contact', 'right', 'regular',
       'Injured his right knee in the first quarter of the Lions'' 35-10 Week 10 win over the Patriots at Allianz Arena in Munich (a designated Lions home game). After a third-down sack of Drake Maye, he leapt to celebrate and his right knee buckled when he landed (non-contact). He walked off and did not return. Initial tests and an MRI in Munich showed a torn right ACL; he is out for the season. Additional tests and a second opinion in the United States are pending, and surgery has not been scheduled. Reports also noted possible additional knee damage, with concern about the meniscus, which has not been confirmed.',
       'https://www.espn.com/nfl/story/_/id/50501291/sources-aidan-hutchinson-season-torn-acl'
FROM players p WHERE p.slug = 'aidan-hutchinson' AND p.league = 'NFL'
  AND NOT EXISTS (SELECT 1 FROM injuries i WHERE i.player_id = p.id AND i.injury_type = 'ACL' AND i.injury_date = '2026-11-15');

-- Update: aidan-hutchinson diagnosis 2026-11-16
INSERT INTO progress_updates (injury_id, update_date, stage, status_label, notes, source)
SELECT i.id, '2026-11-16', 'diagnosis', 'Torn right ACL on initial tests; out for season', 'Ian Rapoport reported that initial tests, including an MRI in Munich, showed a torn ACL in the right knee, and Adam Schefter reported the same initial diagnosis. Out for the season. Additional tests in the U.S. are pending; surgery has not been scheduled. Possible additional meniscus damage was reported as a concern but is not confirmed.', 'https://www.nfl.com/news/lions-aidan-hutchinson-out-for-2026-season-torn-acl'
FROM injuries i JOIN players p ON p.id = i.player_id
WHERE p.slug = 'aidan-hutchinson' AND p.league = 'NFL' AND i.injury_type = 'ACL' AND i.injury_date = '2026-11-15'
  AND NOT EXISTS (SELECT 1 FROM progress_updates x WHERE x.injury_id = i.id AND x.stage = 'diagnosis' AND x.update_date = '2026-11-16');
